draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw dog
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 45);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 45);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw food bowl
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 80, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('FOOD', W/2 + 50, H/2 + 80);

  // draw warning lines
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 100);
  ctx.lineTo(W/2 + 70, H/2 + 100);
  ctx.stroke();

  // draw growling dog mouth
  ctx.beginPath();
  ctx.moveTo(W/2 - 10 + 10 * Math.sin(t), H/2 + 40);
  ctx.lineTo(W/2 + 10 + 10 * Math.sin(t), H/2 + 40);
  ctx.stroke();

  ctx.restore();
}
